"""Access to the three official PS-P1 payloads (generated by the kit's gen_payloads.py)."""
from __future__ import annotations

import hashlib
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
KIT = os.path.join(ROOT, "P1_secure_channel")
PAYLOAD_DIR = os.path.join(KIT, "payloads")
NAMES = ("payload_1KB.bin", "payload_100KB.bin", "payload_10MB.bin")


def official_hashes() -> dict:
    out = {}
    for line in open(os.path.join(KIT, "payload_sha256.txt")):
        if line.strip():
            h, name = line.split()
            out[name] = h
    return out


def ensure_payloads() -> None:
    """Run the organizers' gen_payloads.py if any payload is missing or corrupted."""
    want = official_hashes()
    for n in NAMES:
        p = os.path.join(PAYLOAD_DIR, n)
        if not os.path.exists(p) or sha256_file(p) != want[n]:
            subprocess.run([sys.executable, os.path.join(KIT, "gen_payloads.py")], check=True,
                           stdout=subprocess.DEVNULL)
            break
    for n in NAMES:
        if sha256_file(os.path.join(PAYLOAD_DIR, n)) != want[n]:
            raise RuntimeError(f"{n}: SHA-256 does not match payload_sha256.txt")


def sha256_file(path: str) -> str:
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def load(name: str) -> bytes:
    with open(os.path.join(PAYLOAD_DIR, name), "rb") as f:
        return f.read()


def load_all() -> dict:
    ensure_payloads()
    return {n: load(n) for n in NAMES}
